       WHERE schemaname = 'public' AND tablename = 'event_seat_assignments' AND policyname = 'event_seat_assignments_moderator_write')
     = 'd722d011ab5f96ea93d121b7fbf14679' THEN
    ALTER POLICY "event_seat_assignments_moderator_write" ON public."event_seat_assignments"
    USING (((event_id IN ( SELECT l.event_id FROM current_moderator_area_levels('seat_plan'::text) l WHERE (l.level = 'edit'::text)))))
    WITH CHECK (((event_id IN ( SELECT l.event_id FROM current_moderator_area_levels('seat_plan'::text) l WHERE (l.level = 'edit'::text)))));
  ELSE
    RAISE NOTICE 'rls-once: public.% policy % changed since generation; left as it is', 'event_seat_assignments', 'event_seat_assignments_moderator_write';
  END IF;
END $rls$;

