       WHERE schemaname = 'public' AND tablename = 'patiktok_render_jobs' AND policyname = 'couple_inserts_patiktok_render_jobs')
     = 'd34997ada2b6c98d60ddc48e6221aff9' THEN
    ALTER POLICY "couple_inserts_patiktok_render_jobs" ON public."patiktok_render_jobs"
    WITH CHECK (((event_id IN ( SELECT event_members.event_id
   FROM event_members
  WHERE ((event_members.user_id = ( SELECT auth.uid() AS uid)) AND (event_members.member_type = 'couple'::member_type)))) AND (requested_by = ( SELECT auth.uid() AS uid))));
  ELSE
    RAISE NOTICE 'rls-once: public.% policy % changed since generation; left as it is', 'patiktok_render_jobs', 'couple_inserts_patiktok_render_jobs';
  END IF;
END $rls$;

